func buildTree(preorder []int, inorder []int) *TreeNode {
	pos := make(map[int]int, len(inorder))
	for i, v := range inorder {
		pos[v] = i
	}
	var build func(pl, pr, il, ir int) *TreeNode
	build = func(pl, pr, il, ir int) *TreeNode {
		if pl > pr {
			return nil
		}
		root := &TreeNode{Val: preorder[pl]}
		k := pos[root.Val]
		leftLen := k - il
		root.Left = build(pl+1, pl+leftLen, il, k-1)
		root.Right = build(pl+leftLen+1, pr, k+1, ir)
		return root
	}
	return build(0, len(preorder)-1, 0, len(inorder)-1)
}

