		return nil
	}
	v, _ := strconv.Atoi(f[0])
	root := &TreeNode{Val: v}
	q := []*TreeNode{root}
	i := 1
	for i < len(f) && len(q) > 0 {
		node := q[0]
		q = q[1:]
		if i < len(f) {
			if f[i] != "null" {
				v, _ := strconv.Atoi(f[i])
				node.Left = &TreeNode{Val: v}
				q = append(q, node.Left)
			}
			i++
		}
		if i < len(f) {
			if f[i] != "null" {
				v, _ := strconv.Atoi(f[i])
				node.Right = &TreeNode{Val: v}
				q = append(q, node.Right)
			}
			i++
		}
	}
	return root
}

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	f := strings.Fields(string(data))
	if len(f) == 0 {
		return
	}
	root := build(f)
	best := -1 << 62
	var gain func(node *TreeNode) int
	gain = func(node *TreeNode) int {
		if node == nil {
			return 0
		}
		left := gain(node.Left)
		if left < 0 {
			left = 0
		}
		right := gain(node.Right)
		if right < 0 {
			right = 0
		}
		if s := node.Val + left + right; s > best {
			best = s
		}
		if left > right {
			return node.Val + left
		}
		return node.Val + right
	}
	gain(root)
	fmt.Println(best)
}

