	head, seen := 0, 0
	for head < len(q) {
		cur := q[head]
		head++
		seen++
		for _, nxt := range graph[cur] {
			indeg[nxt]--
			if indeg[nxt] == 0 {
				q = append(q, nxt)
			}
		}
	}
	return seen == numCourses
}

